1	import type {
2	  WorksListResponse,
3	} from "../types/work.types.js";
4	
5	const WORKS_MODAL_PATH = "/works/modal-component";
6	const WORKS_LIST_PATH = "/works/list";
7	
8	export async function fetchWorksModalHtml(
9	  no: string,
10	  signal?: AbortSignal,
11	): Promise<string> {
12	  const path = `${WORKS_MODAL_PATH}/${encodeURIComponent(no)}`;
13	  const response = await fetch(path, {
14	    method: "GET",
15	    signal,
16	    headers: {
17	      "X-Requested-With": "XMLHttpRequest",
18	    },
19	  });
20	  if (!response.ok) {
21	    throw new Error(`Works modal request failed: ${response.status}`);
22	  }
23	  return response.text();
24	}
25	
26	export async function fetchWorksList(
27	  offset: number,
28	  limit: number,
29	  category: string | null,
30	  signal?: AbortSignal,
31	): Promise<WorksListResponse> {
32	  const params = new URLSearchParams({
33	    offset: String(offset),
34	    limit: String(limit),
35	  });
36	  if (category) {
37	    params.set("category", category);
38	  }
39	  const response = await fetch(`${WORKS_LIST_PATH}?${params.toString()}`, {
40	    method: "GET",
41	    signal,
42	    headers: {
43	      "X-Requested-With": "XMLHttpRequest",
44	      Accept: "application/json",
45	    },
46	  });
47	  if (!response.ok) {
48	    throw new Error(`Works list request failed: ${response.status}`);
49	  }
50	  return (await response.json()) as WorksListResponse;
51	}
