1	import * as THREE from "three";
2	
3	// ─── Constants ──────────────────────────────────────────────────────────────
4	
5	const DEPTH_RANGE = 50;
6	const HALF_RANGE = DEPTH_RANGE / 2;
7	const VISIBLE_COUNT = 12;
8	const MAX_HORIZONTAL_OFFSET = 8;
9	const MAX_VERTICAL_OFFSET = 8;
10	
11	const SCROLL_DAMPING = 0.95;
12	const AUTO_PLAY_ACCEL = 0.3;
13	const IDLE_THRESHOLD_MS = 3000;
14	const MAX_SCROLL_VEL = 20.0;
15	const SCROLL_SPEED = 1.0;
16	const MAX_DELTA = 0.1;
17	
18	const FADE_IN_START = 0.05;
19	const FADE_IN_END = 0.25;
20	const FADE_OUT_START = 0.4;
21	const FADE_OUT_END = 0.43;
22	const BLUR_IN_START = 0.0;
23	const BLUR_IN_END = 0.1;
24	const BLUR_OUT_START = 0.4;
25	const BLUR_OUT_END = 0.43;
26	const MAX_BLUR = 8.0;
27	const GALLERY_ENABLE_THRESHOLD = 0.18;
28	
29	const GALLERY_IMAGES: readonly string[] = [
30	  "https://images.unsplash.com/photo-1741332966416-414d8a5b8887?w=600&auto=format&fit=crop&q=60&ixlib=rb-4.1.0&ixid=M3wxMjA3fDB8MHxmZWF0dXJlZC1waG90b3MtZmVlZHw2fHx8ZW58MHx8fHx8",
31	  "https://images.unsplash.com/photo-1754769440490-2eb64d715775?q=80&w=1113&auto=format&fit=crop&ixlib=rb-4.1.0&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D",
32	  "https://images.unsplash.com/photo-1758640920659-0bb864175983?w=600&auto=format&fit=crop&q=60&ixlib=rb-4.1.0&ixid=M3wxMjA3fDB8MHxmZWF0dXJlZC1waG90b3MtZmVlZHwzNHx8fGVufDB8fHx8fA%3D%3D",
33	  "https://plus.unsplash.com/premium_photo-1758367454070-731d3cc11774?w=600&auto=format&fit=crop&q=60&ixlib=rb-4.1.0&ixid=M3wxMjA3fDB8MHxmZWF0dXJlZC1waG90b3MtZmVlZHw0MXx8fGVufDB8fHx8fA%3D%3D",
34	  "https://images.unsplash.com/photo-1746023841657-e5cd7cc90d2c?w=600&auto=format&fit=crop&q=60&ixlib=rb-4.1.0&ixid=M3wxMjA3fDB8MHxmZWF0dXJlZC1waG90b3MtZmVlZHw0Nnx8fGVufDB8fHx8fA%3D%3D",
35	  "https://images.unsplash.com/photo-1741715661559-6149723ea89a?w=600&auto=format&fit=crop&q=60&ixlib=rb-4.1.0&ixid=M3wxMjA3fDB8MHxmZWF0dXJlZC1waG90b3MtZmVlZHw1MHx8fGVufDB8fHx8fA%3D%3D",
36	  "https://images.unsplash.com/photo-1725878746053-407492aa4034?w=600&auto=format&fit=crop&q=60&ixlib=rb-4.1.0&ixid=M3wxMjA3fDB8MHxmZWF0dXJlZC1waG90b3MtZmVlZHw1OHx8fGVufDB8fHx8fA%3D%3D",
37	  "https://images.unsplash.com/photo-1752588975168-d2d7965a6d64?w=600&auto=format&fit=crop&q=60&ixlib=rb-4.1.0&ixid=M3wxMjA3fDB8MHxmZWF0dXJlZC1waG90b3MtZmVlZHw2M3x8fGVufDB8fHx8fA%3D%3D",
38	];
39	
40	// ─── GLSL shaders (exact copy from source component) ───────────────────────
41	
42	const VERTEX_SHADER = /* glsl */ `
43	  uniform float scrollForce;
44	  uniform float time;
45	  uniform float isHovered;
46	  varying vec2 vUv;
47	  varying vec3 vNormal;
48	
49	  void main() {
50	    vUv = uv;
51	    vNormal = normal;
52	
53	    vec3 pos = position;
54	
55	    float curveIntensity = scrollForce * 0.3;
56	    float distanceFromCenter = length(pos.xy);
57	    float curve = distanceFromCenter * distanceFromCenter * curveIntensity;
58	
59	    float ripple1 = sin(pos.x * 2.0 + scrollForce * 3.0) * 0.02;
60	    float ripple2 = sin(pos.y * 2.5 + scrollForce * 2.0) * 0.015;
61	    float clothEffect = (ripple1 + ripple2) * abs(curveIntensity) * 2.0;
62	
63	    float flagWave = 0.0;
64	    if (isHovered > 0.5) {
65	      float wavePhase = pos.x * 3.0 + time * 8.0;
66	      float waveAmplitude = sin(wavePhase) * 0.1;
67	      float dampening = smoothstep(-0.5, 0.5, pos.x);
68	      flagWave = waveAmplitude * dampening;
69	      float secondaryWave = sin(pos.x * 5.0 + time * 12.0) * 0.03 * dampening;
70	      flagWave += secondaryWave;
71	    }
72	
73	    pos.z -= (curve + clothEffect + flagWave);
74	
75	    gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
76	  }
77	`;
78	
79	const FRAGMENT_SHADER = /* glsl */ `
80	  uniform sampler2D map;
81	  uniform float opacity;
82	  uniform float blurAmount;
83	  uniform float scrollForce;
84	  varying vec2 vUv;
85	  varying vec3 vNormal;
86	
87	  void main() {
88	    vec4 color = texture2D(map, vUv);
89	
90	    if (blurAmount > 0.0) {
91	      vec2 texelSize = 1.0 / vec2(textureSize(map, 0));
92	      vec4 blurred = vec4(0.0);
93	      float total = 0.0;
94	
95	      for (float x = -2.0; x <= 2.0; x += 1.0) {
96	        for (float y = -2.0; y <= 2.0; y += 1.0) {
97	          vec2 offset = vec2(x, y) * texelSize * blurAmount;
98	          float weight = 1.0 / (1.0 + length(vec2(x, y)));
99	          blurred += texture2D(map, vUv + offset) * weight;
100	          total += weight;
101	        }
102	      }
103	      color = blurred / total;
104	    }
105	
106	    float curveHighlight = abs(scrollForce) * 0.05;
107	    color.rgb += vec3(curveHighlight * 0.1);
108	
109	    gl_FragColor = vec4(color.rgb, color.a * opacity);
110	  }
111	`;
112	
113	// ─── Helpers ────────────────────────────────────────────────────────────────
114	
115	function loadTexture(
116	  loader: THREE.TextureLoader,
117	  url: string,
118	): Promise<THREE.Texture | null> {
119	  return new Promise((resolve) => {
120	    loader.load(
121	      url,
122	      (texture) => {
123	        texture.minFilter = THREE.LinearFilter;
124	        texture.generateMipmaps = false;
125	        resolve(texture);
126	      },
127	      undefined,
128	      () => resolve(null),
129	    );
130	  });
131	}
132	
133	function computeOpacity(n: number): number {
134	  if (n < FADE_IN_START) return 0;
135	  if (n < FADE_IN_END) return (n - FADE_IN_START) / (FADE_IN_END - FADE_IN_START);
136	  if (n < FADE_OUT_START) return 1;
137	  if (n < FADE_OUT_END) return 1 - (n - FADE_OUT_START) / (FADE_OUT_END - FADE_OUT_START);
138	  return 0;
139	}
140	
141	function computeBlur(n: number): number {
142	  if (n < BLUR_IN_START) return MAX_BLUR;
143	  if (n < BLUR_IN_END) return MAX_BLUR * (1 - (n - BLUR_IN_START) / (BLUR_IN_END - BLUR_IN_START));
144	  if (n < BLUR_OUT_START) return 0;
145	  if (n < BLUR_OUT_END) return MAX_BLUR * ((n - BLUR_OUT_START) / (BLUR_OUT_END - BLUR_OUT_START));
146	  return MAX_BLUR;
147	}
148	
149	// ─── Types ──────────────────────────────────────────────────────────────────
150	
151	interface PlaneData {
152	  index: number;
153	  z: number;
154	  imageIndex: number;
155	  x: number;
156	  y: number;
157	}
158	
159	interface PlaneRecord {
160	  mesh: THREE.Mesh<THREE.PlaneGeometry, THREE.ShaderMaterial>;
161	  data: PlaneData;
162	}
163	
164	// ─── Class ──────────────────────────────────────────────────────────────────
165	
166	export class InfiniteGalleryRenderer {
167	  private _renderer: THREE.WebGLRenderer | null = null;
168	  private _scene: THREE.Scene | null = null;
169	  private _camera: THREE.PerspectiveCamera | null = null;
170	  private _clock: THREE.Clock | null = null;
171	  private _raycaster: THREE.Raycaster | null = null;
172	  private _canvas: HTMLCanvasElement | null = null;
173	
174	  private _planes: PlaneRecord[] = [];
175	  private _meshList: THREE.Object3D[] = [];
176	  private _textures: (THREE.Texture | null)[] = [];
177	  private _geometries: THREE.BufferGeometry[] = [];
178	  private _materials: THREE.ShaderMaterial[] = [];
179	
180	  private _rafId: number | null = null;
181	  private _rendering = false;
182	  private _disposed = false;
183	
184	  private _resizeObserver: ResizeObserver | null = null;
185	  private _intersectionObserver: IntersectionObserver | null = null;
186	
187	  private _scrollVelocity = 0;
188	  private _lastInteractionMs = 0;
189	  private _isAutoPlaying = false;
190	  private _galleryEnabled = false;
191	  private _autoPlayIntervalId: ReturnType<typeof setInterval> | null = null;
192	  private _hoveredIndex = -1;
193	  private _touchLastY = 0;
194	
195	  private readonly _pointerNDC = new THREE.Vector2();
196	
197	  private readonly _onWheel: (e: WheelEvent) => void;
198	  private readonly _onKeyDown: (e: KeyboardEvent) => void;
199	  private readonly _onTouchStart: (e: TouchEvent) => void;
200	  private readonly _onTouchMove: (e: TouchEvent) => void;
201	  private readonly _onPointerMove: (e: PointerEvent) => void;
202	  private readonly _onPointerLeave: (e: PointerEvent) => void;
203	
204	  constructor() {
205	    this._onWheel = (e) => {
206	      e.preventDefault();
207	      this._recordInteraction();
208	      this._scrollVelocity += e.deltaY * 0.01 * SCROLL_SPEED;
209	      this._scrollVelocity = Math.max(-MAX_SCROLL_VEL, Math.min(MAX_SCROLL_VEL, this._scrollVelocity));
210	    };
211	    this._onKeyDown = (e) => {
212	      if (e.key === "ArrowDown" || e.key === "ArrowRight") {
213	        this._recordInteraction();
214	        this._scrollVelocity += 2 * SCROLL_SPEED;
215	      } else if (e.key === "ArrowUp" || e.key === "ArrowLeft") {
216	        this._recordInteraction();
217	        this._scrollVelocity -= 2 * SCROLL_SPEED;
218	      }
219	    };
220	    this._onTouchStart = (e) => {
221	      if (e.touches[0]) this._touchLastY = e.touches[0].clientY;
222	      this._recordInteraction();
223	    };
224	    this._onTouchMove = (e) => {
225	      e.preventDefault();
226	      if (!e.touches[0]) return;
227	      const y = e.touches[0].clientY;
228	      const delta = this._touchLastY - y;
229	      this._touchLastY = y;
230	      this._recordInteraction();
231	      this._scrollVelocity += delta * 0.03 * SCROLL_SPEED;
232	      this._scrollVelocity = Math.max(-MAX_SCROLL_VEL, Math.min(MAX_SCROLL_VEL, this._scrollVelocity));
233	    };
234	    this._onPointerMove = (e) => {
235	      const canvas = this._canvas;
236	      const camera = this._camera;
237	      const raycaster = this._raycaster;
238	      if (!canvas || !camera || !raycaster) return;
239	      const rect = canvas.getBoundingClientRect();
240	      this._pointerNDC.set(
241	        ((e.clientX - rect.left) / rect.width) * 2 - 1,
242	        -((e.clientY - rect.top) / rect.height) * 2 + 1,
243	      );
244	      raycaster.setFromCamera(this._pointerNDC, camera);
245	      const intersects = raycaster.intersectObjects(this._meshList, false);
246	      if (intersects.length > 0) {
247	        const hit = intersects[0]?.object;
248	        this._hoveredIndex = this._planes.findIndex((r) => r.mesh === hit);
249	      } else {
250	        this._hoveredIndex = -1;
251	      }
252	    };
253	    this._onPointerLeave = (_e) => {
254	      this._hoveredIndex = -1;
255	    };
256	  }
257	
258	  async init(canvas: HTMLCanvasElement): Promise<void> {
259	    this._canvas = canvas;
260	
261	    const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
262	    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
263	    renderer.setClearAlpha(0);
264	    this._renderer = renderer;
265	
266	    const scene = new THREE.Scene();
267	    this._scene = scene;
268	
269	    const w = Math.max(canvas.clientWidth, 1);
270	    const h = Math.max(canvas.clientHeight, 1);
271	    const camera = new THREE.PerspectiveCamera(55, w / h, 0.1, 200);
272	    camera.position.set(0, 0, 0);
273	    this._camera = camera;
274	
275	    this._clock = new THREE.Clock();
276	    this._raycaster = new THREE.Raycaster();
277	
278	    const loader = new THREE.TextureLoader();
279	    const textures = await Promise.all(
280	      GALLERY_IMAGES.map((url) => loadTexture(loader, url)),
281	    );
282	    if (this._disposed) return;
283	
284	    this._textures = textures;
285	    this._buildPlanes(textures);
286	    this._syncSize();
287	    this._observeResize();
288	    this._observeVisibility();
289	    this._attachInputListeners();
290	
291	    this._autoPlayIntervalId = setInterval(() => this._tickAutoPlay(), 100);
292	  }
293	
294	  setScrollProgress(p: number): void {
295	    const shouldEnable = p >= GALLERY_ENABLE_THRESHOLD;
296	    if (this._galleryEnabled === shouldEnable) return;
297	    this._galleryEnabled = shouldEnable;
298	    if (!shouldEnable) {
299	      this._isAutoPlaying = false;
300	      this._scrollVelocity = 0;
301	    } else {
302	      this._lastInteractionMs = 0;
303	    }
304	  }
305	
306	  dispose(): void {
307	    this._disposed = true;
308	    this._stopRaf();
309	
310	    if (this._autoPlayIntervalId !== null) {
311	      clearInterval(this._autoPlayIntervalId);
312	      this._autoPlayIntervalId = null;
313	    }
314	
315	    if (this._canvas) this._detachInputListeners();
316	
317	    this._resizeObserver?.disconnect();
318	    this._resizeObserver = null;
319	    this._intersectionObserver?.disconnect();
320	    this._intersectionObserver = null;
321	
322	    this._geometries.forEach((g) => g.dispose());
323	    this._geometries = [];
324	    this._materials.forEach((m) => m.dispose());
325	    this._materials = [];
326	    this._textures.forEach((t) => t?.dispose());
327	    this._textures = [];
328	
329	    this._renderer?.dispose();
330	    this._renderer?.forceContextLoss();
331	    this._renderer = null;
332	    this._scene = null;
333	    this._camera = null;
334	    this._clock = null;
335	    this._raycaster = null;
336	    this._canvas = null;
337	    this._planes = [];
338	    this._meshList = [];
339	  }
340	
341	  private _buildPlanes(textures: (THREE.Texture | null)[]): void {
342	    const count = GALLERY_IMAGES.length;
343	    const scene = this._scene!;
344	
345	    for (let i = 0; i < VISIBLE_COUNT; i++) {
346	      // Spatial spread matching the original golden-angle distribution
347	      const hAngle = (i * 2.618) % (Math.PI * 2);
348	      const vAngle = (i * 1.618 + Math.PI / 3) % (Math.PI * 2);
349	      const hRadius = (i % 3) * 1.2;
350	      const vRadius = ((i + 1) % 4) * 0.8;
351	      const x = (Math.sin(hAngle) * hRadius * MAX_HORIZONTAL_OFFSET) / 3;
352	      const y = (Math.cos(vAngle) * vRadius * MAX_VERTICAL_OFFSET) / 4;
353	      const z = (DEPTH_RANGE / VISIBLE_COUNT) * i;
354	      const imageIndex = i % count;
355	
356	      const geo = new THREE.PlaneGeometry(1, 1, 32, 32);
357	      this._geometries.push(geo);
358	
359	      const mat = new THREE.ShaderMaterial({
360	        transparent: true,
361	        uniforms: {
362	          map: { value: textures[imageIndex] ?? null },
363	          opacity: { value: 0.0 },
364	          blurAmount: { value: 0.0 },
365	          scrollForce: { value: 0.0 },
366	          time: { value: 0.0 },
367	          isHovered: { value: 0.0 },
368	        },
369	        vertexShader: VERTEX_SHADER,
370	        fragmentShader: FRAGMENT_SHADER,
371	      });
372	      this._materials.push(mat);
373	
374	      const mesh = new THREE.Mesh(geo, mat);
375	      mesh.position.set(x, y, z - HALF_RANGE);
376	      this._applyTextureScale(mesh, textures[imageIndex] ?? null);
377	
378	      scene.add(mesh);
379	      this._planes.push({ mesh, data: { index: i, z, imageIndex, x, y } });
380	      this._meshList.push(mesh);
381	    }
382	  }
383	
384	  private _applyTextureScale(
385	    mesh: THREE.Mesh<THREE.PlaneGeometry, THREE.ShaderMaterial>,
386	    tex: THREE.Texture | null,
387	  ): void {
388	    const img = tex?.image as { width?: number; height?: number } | undefined;
389	    if (img?.width && img.height) {
390	      const aspect: number = img.width / img.height;
391	      mesh.scale.set(aspect > 1 ? 2 * aspect : 2, aspect > 1 ? 2 : 2 / aspect, 1);
392	    } else {
393	      mesh.scale.set(2, 2, 1);
394	    }
395	  }
396	
397	  private readonly _tick = (): void => {
398	    if (this._disposed || !this._rendering) return;
399	    this._rafId = requestAnimationFrame(this._tick);
400	
401	    const clock = this._clock!;
402	    const renderer = this._renderer!;
403	    const scene = this._scene!;
404	    const camera = this._camera!;
405	    const count = GALLERY_IMAGES.length;
406	
407	    const delta = Math.min(clock.getDelta(), MAX_DELTA);
408	    const elapsedTime = clock.elapsedTime;
409	
410	    // Frame-rate-independent exponential damping
411	    this._scrollVelocity *= Math.pow(SCROLL_DAMPING, delta * 60);
412	    if (Math.abs(this._scrollVelocity) < 0.0001) this._scrollVelocity = 0;
413	
414	    if (this._isAutoPlaying) {
415	      this._scrollVelocity += AUTO_PLAY_ACCEL * delta;
416	      if (this._scrollVelocity > MAX_SCROLL_VEL) this._scrollVelocity = MAX_SCROLL_VEL;
417	    }
418	
419	    const scrollForceUniform = Math.min(Math.abs(this._scrollVelocity) * 0.1, 1);
420	
421	    for (const record of this._planes) {
422	      const { mesh, data } = record;
423	      const mat = mesh.material;
424	
425	      data.z += this._scrollVelocity * delta * 10;
426	
427	      if (data.z >= DEPTH_RANGE) {
428	        data.z -= DEPTH_RANGE;
429	        data.imageIndex = (data.imageIndex + 1) % count;
430	        mat.uniforms["map"].value = this._textures[data.imageIndex] ?? null;
431	        this._applyTextureScale(mesh, this._textures[data.imageIndex] ?? null);
432	      } else if (data.z < 0) {
433	        data.z += DEPTH_RANGE;
434	        data.imageIndex = ((data.imageIndex - 1) % count + count) % count;
435	        mat.uniforms["map"].value = this._textures[data.imageIndex] ?? null;
436	        this._applyTextureScale(mesh, this._textures[data.imageIndex] ?? null);
437	      }
438	
439	      mesh.position.z = data.z - HALF_RANGE;
440	
441	      const n = data.z / DEPTH_RANGE;
442	      mat.uniforms["opacity"].value = computeOpacity(n);
443	      mat.uniforms["blurAmount"].value = computeBlur(n);
444	      mat.uniforms["scrollForce"].value = scrollForceUniform;
445	      mat.uniforms["time"].value = elapsedTime;
446	      mat.uniforms["isHovered"].value = data.index === this._hoveredIndex ? 1.0 : 0.0;
447	    }
448	
449	    renderer.render(scene, camera);
450	  };
451	
452	  private _startRaf(): void {
453	    if (this._rafId !== null || this._disposed) return;
454	    this._rendering = true;
455	    this._rafId = requestAnimationFrame(this._tick);
456	  }
457	
458	  private _stopRaf(): void {
459	    this._rendering = false;
460	    if (this._rafId !== null) {
461	      cancelAnimationFrame(this._rafId);
462	      this._rafId = null;
463	    }
464	  }
465	
466	  private _recordInteraction(): void {
467	    this._lastInteractionMs = performance.now();
468	    this._isAutoPlaying = false;
469	  }
470	
471	  private _tickAutoPlay(): void {
472	    if (this._disposed) {
473	      if (this._autoPlayIntervalId !== null) {
474	        clearInterval(this._autoPlayIntervalId);
475	        this._autoPlayIntervalId = null;
476	      }
477	      return;
478	    }
479	    if (!this._galleryEnabled) {
480	      this._isAutoPlaying = false;
481	      return;
482	    }
483	    this._isAutoPlaying = performance.now() - this._lastInteractionMs > IDLE_THRESHOLD_MS;
484	  }
485	
